-- Migración aditiva: zona empresarial. No modifica ni borra tablas domésticas.
-- Aplicar: mysql -u <admin> kwhtrack < 002_enterprise.up.sql   (revertir: 002_enterprise.down.sql)
CREATE TABLE IF NOT EXISTS organizations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS org_users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,org_role ENUM('owner','member') NOT NULL DEFAULT 'owner',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,INDEX(organization_id));
CREATE TABLE IF NOT EXISTS org_sessions (token_hash BINARY(32) PRIMARY KEY,org_user_id INT UNSIGNED NOT NULL,csrf_token CHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,FOREIGN KEY(org_user_id) REFERENCES org_users(id) ON DELETE CASCADE,INDEX(org_user_id),INDEX(expires_at));
CREATE TABLE IF NOT EXISTS buildings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id INT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,city VARCHAR(80) NULL,is_demo BOOLEAN NOT NULL DEFAULT FALSE,revision BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,INDEX(organization_id));
CREATE TABLE IF NOT EXISTS floors (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,building_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,position SMALLINT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(building_id) REFERENCES buildings(id) ON DELETE CASCADE,INDEX(building_id));
CREATE TABLE IF NOT EXISTS spaces (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,floor_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,kind VARCHAR(40) NOT NULL DEFAULT 'Otro',position SMALLINT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(floor_id) REFERENCES floors(id) ON DELETE CASCADE,INDEX(floor_id));
CREATE TABLE IF NOT EXISTS equipment (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,space_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,category VARCHAR(50) NOT NULL DEFAULT 'Otro',calculation_mode ENUM('power','monthly') NOT NULL DEFAULT 'power',quantity INT UNSIGNED NOT NULL DEFAULT 1,watts DOUBLE NULL,hours DOUBLE NULL,days TINYINT UNSIGNED NULL,factor DOUBLE NOT NULL DEFAULT 1,monthly_kwh DOUBLE NULL,FOREIGN KEY(space_id) REFERENCES spaces(id) ON DELETE CASCADE,INDEX(space_id),CHECK(quantity BETWEEN 1 AND 1000),CHECK(watts IS NULL OR watts>0),CHECK(hours IS NULL OR hours BETWEEN 0 AND 24),CHECK(days IS NULL OR days BETWEEN 0 AND 31),CHECK(factor BETWEEN 0 AND 1),CHECK(monthly_kwh IS NULL OR monthly_kwh>=0));
CREATE TABLE IF NOT EXISTS consumption_records (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,building_id INT UNSIGNED NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,kwh DOUBLE NOT NULL,origin ENUM('measured','bill','imported') NOT NULL,FOREIGN KEY(building_id) REFERENCES buildings(id) ON DELETE CASCADE,INDEX(building_id),CHECK(period_end>=period_start),CHECK(kwh>=0));
